import { Group, Mesh, PlaneGeometry, CylinderGeometry, Color } from 'three/webgpu';
import { uv, mix } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // Helper to create gradient material for a card
  const createCardMaterial = () => {
    const mat = new MeshStandardNodeMaterial();
    const gradient = mix(new Color('#191921'), new Color('#121218'), uv().y);
    mat.colorNode = gradient;
    mat.metalness = 0.25;
    mat.roughness = 0.6;
    mat.clearcoat = 0.15;
    mat.transparent = true;
    mat.opacity = 0; // start invisible for entrance animation
    return mat;
  };

  // Disc material (machined metal)
  const createDiscMaterial = () => {
    const discMat = new MeshStandardNodeMaterial();
    discMat.metalness = 0.5;
    discMat.roughness = 0.55;
    discMat.clearcoat = 0.2;
    discMat.anisotropy = 0.6; // brushed anisotropy
    discMat.emissive = new Color('#ff2a38');
    discMat.emissiveIntensity = 1.6;
    discMat.metalness = 0.5;
    return discMat;
  };

  // Layout constants
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const TOTAL_W = 5.0;
  const START_X = -TOTAL_W / 2 + CARD_W / 2; // -1.75
  const PADDING = 0.375; // interior padding
  const ICON_DIAM = 0.4;
  const ICON_THICK = 0.05;
  const ICON_GAP = 0.25;
  const TITLE_GAP = 0.125;

  const textItems = [
    { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
  ];

  const cardGroups = [];
  const liftTimelines = [];
  const entranceTimeline = gsap.timeline({ paused: true });

  textItems.forEach((item, idx) => {
    const cardGroup = new Group();
    cardGroup.name = `card-${idx + 1}`;
    const xPos = START_X + idx * (CARD_W + GAP);
    cardGroup.position.set(xPos, 0, 0);
    root.add(cardGroup);
    cardGroups.push(cardGroup);

    // Card plane
    const cardGeom = new PlaneGeometry(CARD_W, CARD_H);
    const cardMat = createCardMaterial();
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardMesh.name = 'card-plane';
    cardGroup.add(cardMesh);

    // Icon disc
    const discGeom = new CylinderGeometry(ICON_DIAM / 2, ICON_DIAM / 2, ICON_THICK, 32);
    const discMat = createDiscMaterial();
    const discMesh = new Mesh(discGeom, discMat);
    // orient disc to face camera (+Z)
    discMesh.rotation.x = Math.PI / 2;
    // position disc near top inside padding
    const topEdgeY = CARD_H / 2 - PADDING - ICON_DIAM / 2;
    discMesh.position.set(0, topEdgeY, 0.001);
    cardGroup.add(discMesh);

    // Glyph text on disc
    const glyphText = ctx.fontAtlas.createText(item.glyph, {
      fontSize: 20,
      color: '#ff2a38',
      align: 'center',
    });
    glyphText.position.set(0, 0, ICON_THICK / 2 + 0.001);
    discMesh.add(glyphText);
    // ensure emissive intensity adjustment affects glyph’s material if possible
    if (glyphText.material) {
      glyphText.material.emissive = new Color('#ff2a38');
      glyphText.material.emissiveIntensity = 1.6;
    }

    // Title text
    const titleY = topEdgeY - ICON_DIAM / 2 - ICON_GAP - 0.2; // approximate offset
    const titleText = ctx.fontAtlas.createText(item.title, {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'center',
    });
    titleText.position.set(0, titleY, 0.01);
    cardGroup.add(titleText);

    // Body text
    const bodyY = titleY - 0.4 - TITLE_GAP; // approximate offset
    const bodyText = ctx.fontAtlas.createText(item.body, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
    });
    bodyText.position.set(0, bodyY, 0.01);
    cardGroup.add(bodyText);

    // Entrance animation per card
    entranceTimeline.fromTo(
      cardMesh.material,
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'power2.out' },
      idx * 0.08
    );
    entranceTimeline.fromTo(
      cardGroup.position,
      { y: 0.2 },
      { y: 0, duration: 0.5, ease: 'power2.out' },
      idx * 0.08
    );

    // Hover lift timeline (paused, will be played on hover)
    const liftTl = gsap.timeline({ paused: true });
    liftTl.to(
      cardGroup.position,
      { y: 0.06, duration: 0.18, ease: 'power2.out' },
      0
    );
    liftTl.to(
      discMat,
      { emissiveIntensity: 2.2, duration: 0.18, ease: 'power2.out' },
      0
    );
    liftTimelines.push(liftTl);

    // Handlers for interaction
    cardGroup.userData.handlers = {
      hover: () => {
        liftTl.play(0);
      },
      out: () => {
        liftTl.reverse();
      },
    };
  });

  // start entrance animation
  entranceTimeline.play();

  // Cleanup
  root.userData.cleanup = () => {
    entranceTimeline.kill();
    liftTimelines.forEach((tl) => tl.kill());
    // dispose geometries and materials
    cardGroups.forEach((cg) => {
      cg.traverse((obj) => {
        if (obj.isMesh) {
          obj.geometry.dispose();
          if (obj.material) {
            obj.material.dispose();
          }
        }
      });
    });
  };

  return root;
}
